package dev.shadw.khemet.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Crocodile with its own model and texture. Generated by shadw-mod mob. */
public class CrocodileRenderer extends MobRenderer<Crocodile, CrocodileModel.State, CrocodileModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/crocodile.png");

	public CrocodileRenderer(EntityRendererProvider.Context context) {
		super(context, new CrocodileModel(context.bakeLayer(CrocodileModel.LAYER)), 1.0F);
	}

	@Override
	public CrocodileModel.State createRenderState() {
		return new CrocodileModel.State();
	}

	@Override
	public void extractRenderState(Crocodile entity, CrocodileModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(CrocodileModel.State state) {
		return TEXTURE;
	}
}
